import { Meter as BaseMeter } from '@base-ui/react/meter';
import type { ReactNode, Ref } from 'react';
import { cn } from '../../utils/cn';
import { getMeterLevel, meterVariants, type MeterThresholds, type MeterVariantProps } from './meter.variants';

export interface MeterProps extends Omit<BaseMeter.Root.Props, 'className' | 'children'>, Omit<MeterVariantProps, 'level'> {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  /** Visible label; also the accessible name. Without it, pass `aria-label`. */
  label?: ReactNode;
  /** Replaces the formatted value, e.g. "8.2k / 10k requests". Pair with `aria-valuetext`. */
  valueLabel?: ReactNode;
  /** Hides the value text. */
  hideValue?: boolean;
  /** Percent-of-max thresholds for the warning and destructive levels. */
  thresholds?: MeterThresholds;
  /**
   * Inverts the thresholds: low values are bad (scores, health, remaining budget). Default
   * false (high is bad, as for quotas). Defaults become warning ≤ 50 %, destructive ≤ 20 %.
   */
  higherIsBetter?: boolean;
  /** Helper line under the bar, coloured by level (e.g. "Overage billed at $0.002 / request"). */
  note?: ReactNode;
}

/**
 * Quota / usage meter (role="meter") on Base UI Meter. Values over `max` are clamped for
 * assistive tech and the bar, but the level (and your `valueLabel`) reflect the overage.
 */
export function Meter({
  value,
  min = 0,
  max = 100,
  size,
  label,
  valueLabel,
  hideValue = false,
  thresholds,
  higherIsBetter = false,
  note,
  className,
  ...props
}: MeterProps) {
  const range = max - min;
  const percent = range > 0 ? ((value - min) / range) * 100 : 0;
  const level = getMeterLevel(percent, thresholds, higherIsBetter);
  const s = meterVariants({ level, size });
  const clamped = Math.min(Math.max(value, min), max);
  return (
    <BaseMeter.Root value={clamped} min={min} max={max} data-level={level} className={cn(s.root(), className)} {...props}>
      {(label != null || !hideValue) && (
        <div className={s.header()}>
          {label != null ? <BaseMeter.Label className={s.label()}>{label}</BaseMeter.Label> : <span />}
          {!hideValue && (valueLabel != null ? <span className={s.value()}>{valueLabel}</span> : <BaseMeter.Value className={s.value()} />)}
        </div>
      )}
      <BaseMeter.Track className={s.track()}>
        <BaseMeter.Indicator className={s.indicator()} />
      </BaseMeter.Track>
      {note != null && <p className={s.note()}>{note}</p>}
    </BaseMeter.Root>
  );
}

export { Meter, type MeterProps } from './Meter';
export { meterVariants, getMeterLevel, type MeterVariantProps, type MeterLevel, type MeterThresholds } from './meter.variants';
export { doc as meterDoc } from './Meter.doc';

import { tv, type VariantProps } from '../../utils/tv';

/**
 * Usage meter. The level comes from the thresholds: green while healthy, amber near the cap,
 * red at or over it. The brand green never signals severity on its own.
 */
export const meterVariants = tv({
  slots: {
    root: 'grid w-full gap-1.5',
    header: 'flex items-baseline justify-between gap-3',
    label: 'text-[13px] font-medium text-foreground',
    value: 'font-mono text-[11.5px] font-semibold tabular-nums',
    track: 'relative w-full overflow-hidden rounded-full bg-secondary',
    indicator: 'block h-full rounded-full transition-[width] duration-400 ease-out motion-reduce:transition-none',
    note: 'font-mono text-[11px]',
  },
  variants: {
    level: {
      ok: { indicator: 'bg-primary', value: 'text-foreground', note: 'text-muted-foreground' },
      warning: { indicator: 'bg-warning', value: 'text-warning-text', note: 'text-warning-text' },
      critical: { indicator: 'bg-destructive', value: 'text-destructive-text', note: 'text-destructive-text' },
    },
    size: {
      sm: { track: 'h-1.5' },
      md: { track: 'h-2' },
      lg: { track: 'h-2.5' },
    },
  },
  defaultVariants: { level: 'ok', size: 'md' },
});

export type MeterVariantProps = VariantProps<typeof meterVariants>;
export type MeterLevel = NonNullable<MeterVariantProps['level']>;

export interface MeterThresholds {
  /**
   * Percent of max at which the meter turns amber. Default 80 (at or above). With
   * `higherIsBetter`, the meter turns amber at or below it; default 50.
   */
  warning?: number;
  /**
   * Percent of max at which the meter turns red. Default 100 (at or above). With
   * `higherIsBetter`, the meter turns red at or below it; default 20.
   */
  destructive?: number;
}

/**
 * Maps a percentage of max to a level using the thresholds. By default high is bad (quotas);
 * pass `higherIsBetter` for scores, health or remaining budget, where low is bad.
 */
export function getMeterLevel(percent: number, thresholds: MeterThresholds = {}, higherIsBetter = false): MeterLevel {
  if (higherIsBetter) {
    const { warning = 50, destructive = 20 } = thresholds;
    if (percent <= destructive) return 'critical';
    if (percent <= warning) return 'warning';
    return 'ok';
  }
  const { warning = 80, destructive = 100 } = thresholds;
  if (percent >= destructive) return 'critical';
  if (percent >= warning) return 'warning';
  return 'ok';
}

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'Meter',
  group: 'Feedback',
  status: 'stable',
  description: 'Usage meter for quotas and limits: label, value text, and a level set by thresholds (healthy → warning near the cap → destructive at or over it), with an optional note under the bar. `higherIsBetter` inverts the thresholds for scores and health (low = warning / destructive).',
  primitive: '@base-ui/react/meter',
  pattern: 'meter',
  tokens: ['primary', 'warning', 'warning-text', 'destructive', 'destructive-text', 'secondary', 'foreground', 'muted-foreground'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
